WITH UserReputation AS (SELECT Id, Reputation, DisplayName, RANK() OVER (ORDER BY Reputation DESC NULLS FIRST) AS ReputationRank FROM Users), PopularPosts AS (SELECT Id, PostTypeId, OwnerUserId, Score, ViewCount, RANK() OVER (PARTITION BY PostTypeId ORDER BY Score DESC NULLS FIRST) AS PopularityRank FROM Posts WHERE CreationDate >= CAST('2024-10-01' AS Nullable(DATE)) - INTERVAL '30' DAYS), CommentsCount AS (SELECT PostId, COUNT(*) AS TotalComments FROM Comments GROUP BY PostId), CloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReasonNames FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId) SELECT ur.DisplayName, ur.Reputation, pp.Id AS PopularPostId, pp.Score, pp.ViewCount, COALESCE(cc.TotalComments, 0) AS CommentCount, cr.CloseReasonNames FROM UserReputation AS ur LEFT JOIN PopularPosts AS pp ON ur.Id = pp.OwnerUserId LEFT JOIN CommentsCount AS cc ON pp.Id = cc.PostId LEFT JOIN CloseReasons AS cr ON pp.Id = cr.PostId WHERE pp.PopularityRank <= 10 ORDER BY ur.Reputation DESC NULLS FIRST, pp.Score DESC NULLS FIRST